  for(language,theme)in[("en","light"),("ar","dark")]{for name in["empty","earned","robots","pending","storage"]{
   let state=states[name],window=UIWindow(windowScene:scene);window.frame=CGRect(x:0,y:0,width:402,height:874);let config=WKWebViewConfiguration();config.websiteDataStore = .nonPersistent();let web=WKWebView(frame:window.frame,configuration:config),vc=UIViewController();vc.view=web;window.rootViewController=vc;window.makeKeyAndVisible();web.scrollView.contentInsetAdjustmentBehavior = .never;defer{web.stopLoading();window.isHidden=true;window.rootViewController=nil}
   web.load(URLRequest(url:URL(string:"http://127.0.0.1:5181/__piyali-achievements?state=\(name)&language=\(language)&theme=\(theme)")!));var ready=false;for _ in 0..<600{ready=(try? await web.evaluateJavaScript("document.fonts.status==='loaded' && !!document.querySelector('.achievement-card canvas')"))as?Bool == true;if ready{break};try await Task.sleep(for:.milliseconds(50))};XCTAssertTrue(ready,"Source \(name) \(language)");guard ready else{let detail=(try? await web.evaluateJavaScript("JSON.stringify({url:location.href,body:document.body.innerText,errors:window.achievementErrors||[]})"))as?String ?? "No browser state";let a=XCTAttachment(string:detail);a.name="Achievement preview loading failure";a.lifetime = .keepAlways;add(a);return};_=try await web.evaluateJavaScript("document.querySelectorAll('canvas').forEach(e=>e.style.animationPlayState='paused')");try await Task.sleep(for:.milliseconds(300))
