 func testEveryAchievementPatternRendersColorAndAllLocalizedCharactersExist()throws{
  let data=AchievementUI.source.data,host=VoiceOrbHost(frame:CGRect(x:0,y:0,width:152,height:152));host.layoutIfNeeded();defer{host.stop()};var seen=Set<String>(),rendered=Set<Data>()
  for item in data["items"]["en"].array{let orb=item["orb"];XCTAssertEqual(data["visuals"]["expressions"][orb["mood"].string].array.count,263,item["id"].string);XCTAssertEqual(data["visuals"]["palettes"].array.filter{$0["id"] == orb["palette"]}.count,1,item["id"].string);XCTAssertGreaterThan(data["visuals"]["durations"][orb["reaction"].string].number,0,item["id"].string)}
  for orb in data["items"]["en"].array.map({$0["orb"]}) where seen.insert(orb["state"].string).inserted{
   XCTAssertEqual(data["visuals"]["expressions"][orb["mood"].string].array.count,263);XCTAssertEqual(data["visuals"]["palettes"].array.filter{$0["id"] == orb["palette"]}.count,1)
   let visual=orb.setting("palette",.string("award-jade")).setting("mood",.string("joy"));host.configure(VoiceOrbView(callActive:true,personality:.init(mood:"joy",state:visual["state"].string,reaction:visual["reaction"].string),dark:true,reducedMotion:true,achievement:visual));let image=host.sceneView.snapshot(),cg=try XCTUnwrap(image.cgImage);var bytes=[UInt8](repeating:0,count:cg.width*cg.height*4);let context=try XCTUnwrap(CGContext(data:&bytes,width:cg.width,height:cg.height,bitsPerComponent:8,bytesPerRow:cg.width*4,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.premultipliedLast.rawValue));context.draw(cg,in:CGRect(x:0,y:0,width:cg.width,height:cg.height));rendered.insert(Data(bytes));var colored=0;for i in stride(from:0,to:bytes.count,by:4){let r=Int(bytes[i]),g=Int(bytes[i+1]),b=Int(bytes[i+2]);if bytes[i+3]>240,max(r,g,b)-min(r,g,b)>15{colored += 1}};XCTAssertGreaterThan(colored,350,orb["state"].string+" must render its source pigment, not a plain shader fallback");let a=XCTAttachment(image:image);a.name="Native achievement pattern "+orb["state"].string;a.lifetime = .keepAlways;add(a)
  }
  XCTAssertEqual(seen.count,20);XCTAssertEqual(rendered.count,20,"Twenty patterns with the same palette and eyes must produce twenty distinct surfaces")
